    import uvloop

    asyncio.set_event_loop_policy(uvloop.EventLoopPolicy())
    warnings.filterwarnings('ignore')
except (ModuleNotFoundError, ImportError):
    pass


class BaseManager(object):

    def __init__(self):
        self.ioloop = asyncio.get_event_loop()
        self._is_exiting = False
        self._is_running = False

        self.loop_interval = 1
        self.register_signal_handlers()

    def register_signal_handlers(self):
        for signame in ('SIGINT', 'SIGTERM'):
            self.ioloop.add_signal_handler(
                getattr(signal, signame),
                functools.partial(self.shutdown, signame)
            )

    def shutdown(self, sign):
        """Handle shutdown signal"""
        print(sign)
        if self._is_exiting:
            return

        self._is_exiting = True
        self.ioloop.create_task(self.before_exit())

    async def before_exit(self):
        """Do clean up jobs"""
        try:
            await self.on_before_exit()
        except Exception as e:
            pass
        if self._is_running:
            self.ioloop.stop()
            self._is_running = False
            pass
        else:
            pass

    async def on_before_exit(self):
        pass

    async def main_loop(self):
        self._is_running = True
        while not self._is_exiting:
            try:
                await self.loop_once()
            except KeyboardInterrupt as e:
                raise e
            except Exception as e:
                continue

    async def loop_once(self):
        print('iiiiiiiiiiii')
        await asyncio.sleep(0.5)

    def run(self):
        self.ioloop.create_task(self.main_loop())
        self.ioloop.run_forever()


if __name__ == '__main__':
    b = BaseManager()
